SELECT CASE WHEN s.rating >= 3.8 THEN 'high' WHEN s.rating >= 1.5 THEN 'mid' ELSE 'low' END AS rating_bucket, s.city, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(p.category))) AS category_values, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(p.brand))) AS brand_values FROM products p INNER JOIN suppliers s ON p.supplier_id = s.id WHERE s.city IN ('London', 'Bangkok') GROUP BY CASE WHEN s.rating >= 3.8 THEN 'high' WHEN s.rating >= 1.5 THEN 'mid' ELSE 'low' END, s.city
